import abc


class ManagedObjectAttribute(object):
    def __init__(self, xml_node):
        self.xml_node = xml_node
        self.value = self.get_value()
        self.emss_value = None

    def get_name(self):
        return self.xml_node.attributes["name"].value

    def set_emss_value(self, emss_value):
        self.emss_value = emss_value

    def is_scalar(self):
        return self.xml_node.nodeName == "p"

    @abc.abstractmethod
    def get_value(self):
        pass

    def get_emss_value(self):
        return self.emss_value


class ManagedObjectScalarAttribute(ManagedObjectAttribute):
    def get_value(self):
        if self.xml_node.firstChild:
            return self.xml_node.firstChild.data
        return ""


class ManagedObjectStructuralAttribute(ManagedObjectAttribute):
    def __init__(self, xml_node):
        super(ManagedObjectStructuralAttribute, self).__init__(xml_node)

    def has_subattributes(self):
        return any(child_node.nodeName == "item" for child_node in self.xml_node.childNodes)

    def get_value(self):
        if self.has_subattributes():
            return self.get_dict_type_value()
        else:
            return self.get_list_type_value()

    def get_dict_type_value(self):
        return [self.get_dict_record(node_record) for node_record in self.get_nodes_with_dict_record()]

    def get_nodes_with_dict_record(self):
        return [node for node in self.xml_node.childNodes if node.nodeName == "item"]

    def get_dict_record(self, record_node):
        subattributes = [ManagedObjectScalarAttribute(subattribute_node) for subattribute_node in record_node.childNodes if
                         subattribute_node.nodeName == "p"]
        return {subattribute.get_name(): subattribute.get_value() for subattribute in subattributes}

    def get_list_record(self, record_node):
        return ManagedObjectScalarAttribute(record_node).get_value()

    def get_nodes_with_list_record(self):
        return [node for node in self.xml_node.childNodes if node.nodeName == "p"]

    def get_list_type_value(self):
        return [self.get_list_record(node_record) for node_record in self.get_nodes_with_list_record()]
